 public function request($type,$id,$reason,array$user){$reason=trim($reason);if($reason==='')throw new RuntimeException('Le motif d’annulation est obligatoire.');$this->db->beginTransaction();try{$policy=$this->policy($type);$record=$this->record($type,$id,true);Auth::requireSiteAccess($record['site_id']);Auth::requirePermission($policy['component'],$policy['authorized_action'],$record['site_id']);if(!in_array($record['status'],explode(',',$policy['allowed_statuses']),true))throw new RuntimeException('Annulation interdite au statut '.$record['status'].'.');if($this->scalar("SELECT COUNT(*) FROM cancellation_reversals WHERE entity_type=? AND entity_id=?",[$type,$id]))throw new RuntimeException('Cette opération a déjà été annulée.');if($this->scalar("SELECT COUNT(*) FROM cancellation_requests WHERE entity_type=? AND entity_id=? AND status IN('pending_approval','approved') FOR UPDATE",[$type,$id]))throw new RuntimeException('Une demande d’annulation est déjà active.');$approval=$this->needsApproval($record['status']);$number='ANN-'.date('YmdHis').'-'.random_int(100,999);$this->query("INSERT INTO cancellation_requests(request_number,entity_type,entity_id,site_id,original_status,reason,status,requested_by,requested_at) VALUES(:number,:type,:entity,:site,:old,:reason,:status,:user,NOW())",['number'=>$number,'type'=>$type,'entity'=>$id,'site'=>$record['site_id'],'old'=>$record['status'],'reason'=>$reason,'status'=>$approval?'pending_approval':'approved','user'=>$user['id']]);$request=(int)$this->db->lastInsertId();$this->event($request,'requested',$user['id'],$reason);if(!$approval){$this->executeLocked($request,$user);}$this->db->commit();return$request;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function approve($requestId,array$user){$this->db->beginTransaction();try{$r=$this->row("SELECT * FROM cancellation_requests WHERE id=? FOR UPDATE",[$requestId]);if(!$r||$r['status']!=='pending_approval')throw new RuntimeException('Demande non approuvable.');Auth::requireSiteAccess($r['site_id']);Auth::requirePermission('cancellations','validate',$r['site_id']);if((int)$r['requested_by']===(int)$user['id'])throw new RuntimeException('Le demandeur ne peut pas approuver sa propre annulation.');$this->query("UPDATE cancellation_requests SET status='approved',approved_by=:user,approved_at=NOW() WHERE id=:id",['user'=>$user['id'],'id'=>$r['id']]);$this->event($r['id'],'approved',$user['id'],null);$this->executeLocked($r['id'],$user);$this->db->commit();}catch(Exception$e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}
