 private function executeLocked($requestId,array$user){$r=$this->row("SELECT * FROM cancellation_requests WHERE id=? FOR UPDATE",[$requestId]);if(!$r||$r['status']!=='approved')throw new RuntimeException('Demande non exécutable.');if($this->scalar("SELECT COUNT(*) FROM cancellation_reversals WHERE entity_type=? AND entity_id=?",[$r['entity_type'],$r['entity_id']]))throw new RuntimeException('Annulation déjà exécutée.');$record=$this->record($r['entity_type'],$r['entity_id'],true);if($record['status']==='cancelled')throw new RuntimeException('Opération déjà annulée.');$number='CTR-'.$r['request_number'];$this->query('INSERT INTO cancellation_reversals(request_id,entity_type,entity_id,original_status,reversal_number,executed_by,executed_at) VALUES(:request,:type,:entity,:old,:number,:user,NOW())',['request'=>$r['id'],'type'=>$r['entity_type'],'entity'=>$r['entity_id'],'old'=>$record['status'],'number'=>$number,'user'=>$user['id']]);$reversal=(int)$this->db->lastInsertId();$method='reverse'.str_replace(' ','',ucwords(str_replace('_',' ',$r['entity_type'])));if(!method_exists($this,$method))throw new RuntimeException('Procédure inverse non disponible.');$this->$method($record,$reversal,$user);$this->cancelDocuments($r['entity_type'],$r['entity_id'],$r['reason'],$user);$this->query("UPDATE cancellation_requests SET status='completed',completed_at=NOW() WHERE id=:id",['id'=>$r['id']]);$this->event($r['id'],'executed',$user['id'],$number);$this->audit($r,$record,$reversal,$user);}
 private function reverseWeighing($w,$rev,$u){if($w['status']==='validated'){$m=$this->row("SELECT * FROM silo_movements WHERE weighing_id=? AND movement_type='in' AND status='validated' FOR UPDATE",[$w['id']]);if($m){if($this->scalar("SELECT COUNT(*) FROM machine_feeds WHERE silo_movement_id=? AND status<>'cancelled' AND deleted_at IS NULL",[$m['id']]))throw new RuntimeException('Annulation bloquée: la matière a déjà alimenté une machine.');$s=$this->row('SELECT * FROM silos WHERE id=? FOR UPDATE',[$m['silo_id']]);$after=(float)$s['current_stock_kg']-(float)$m['quantity_kg'];if($after<0)throw new RuntimeException('Stock silo insuffisant pour la contre-opération.');$this->query('UPDATE silos SET current_stock_kg=:q WHERE id=:id',['q'=>$after,'id'=>$s['id']]);$this->effect($rev,'silos',$s['id'],'current_stock_kg',-(float)$m['quantity_kg'],$s['current_stock_kg'],$after,'silo_movements',$m['id']);$this->query("INSERT INTO silo_movements(site_id,silo_id,product_id,weighing_id,movement_type,quantity_kg,stock_before_kg,stock_after_kg,movement_at,status,created_by) VALUES(:site,:silo,:product,:weighing,'adjustment',:qty,:before,:after,NOW(),'validated',:user)",['site'=>$w['site_id'],'silo'=>$s['id'],'product'=>$m['product_id'],'weighing'=>$w['id'],'qty'=>-$m['quantity_kg'],'before'=>$s['current_stock_kg'],'after'=>$after,'user'=>$u['id']]);$this->query("UPDATE silo_movements SET status='cancelled' WHERE id=:id",['id'=>$m['id']]);}}$this->query("UPDATE weighings SET status='cancelled' WHERE id=:id",['id'=>$w['id']]);}
