 private function reverseBss($f,$rev,$u){if($this->scalar("SELECT COUNT(*) FROM production_batches WHERE machine_feed_id=? AND status<>'cancelled' AND deleted_at IS NULL",[$f['id']]))throw new RuntimeException('Annulation bloquée: un lot de production dépend du BSS.');$m=$this->row("SELECT * FROM silo_movements WHERE id=? AND movement_type='out' FOR UPDATE",[$f['silo_movement_id']]);if($m){$s=$this->row('SELECT * FROM silos WHERE id=? FOR UPDATE',[$f['silo_id']]);$after=(float)$s['current_stock_kg']+(float)$f['quantity_kg'];if($after>(float)$s['capacity_kg'])throw new RuntimeException('Capacité silo dépassée par la contre-opération.');$this->query('UPDATE silos SET current_stock_kg=:q WHERE id=:id',['q'=>$after,'id'=>$s['id']]);$this->effect($rev,'silos',$s['id'],'current_stock_kg',$f['quantity_kg'],$s['current_stock_kg'],$after,'silo_movements',$m['id']);$this->query("INSERT INTO silo_movements(site_id,silo_id,product_id,movement_type,quantity_kg,stock_before_kg,stock_after_kg,movement_at,status,created_by) VALUES(:site,:silo,:product,'adjustment',:qty,:before,:after,NOW(),'validated',:user)",['site'=>$f['site_id'],'silo'=>$s['id'],'product'=>$f['product_id'],'qty'=>$f['quantity_kg'],'before'=>$s['current_stock_kg'],'after'=>$after,'user'=>$u['id']]);$this->query("UPDATE silo_movements SET status='cancelled' WHERE id=:id",['id'=>$m['id']]);}$this->query("UPDATE machine_feeds SET status='cancelled' WHERE id=:id",['id'=>$f['id']]);}
 private function reverseTransfer($t,$rev,$u){if(!in_array($t['status'],['draft','submitted','approved','reserved'],true))throw new RuntimeException('Une expédition/réception existe: utilisez le processus de retour complet.');foreach($this->all('SELECT i.*,i.reserved_bags item_reserved_bags,i.reserved_kg item_reserved_kg,fs.reserved_bags stock_reserved_bags,fs.reserved_weight_kg stock_reserved_weight_kg FROM stock_transfer_items i JOIN finished_stocks fs ON fs.id=i.source_finished_stock_id WHERE i.transfer_id=? FOR UPDATE',[$t['id']])as$i){$bags=(int)$i['item_reserved_bags'];$kg=(float)$i['item_reserved_kg'];if($bags>0){if((int)$i['stock_reserved_bags']<$bags||(float)$i['stock_reserved_weight_kg']+0.001<$kg)throw new RuntimeException('Réservation de transfert incohérente.');$this->query('UPDATE finished_stocks SET reserved_bags=reserved_bags-:b,reserved_weight_kg=reserved_weight_kg-:q WHERE id=:id',['b'=>$bags,'q'=>$kg,'id'=>$i['source_finished_stock_id']]);$this->effect($rev,'finished_stocks',$i['source_finished_stock_id'],'reserved_weight_kg',-$kg,$i['stock_reserved_weight_kg'],$i['stock_reserved_weight_kg']-$kg,null,null);$this->query("UPDATE stock_transfer_reservations SET status='released',released_at=NOW() WHERE transfer_item_id=:id AND status='active'",['id'=>$i['id']]);}}$this->query("UPDATE stock_transfers SET status='cancelled' WHERE id=:id",['id'=>$t['id']]);}
 private function reverseProduction($b,$rev,$u){if($this->scalar("SELECT COUNT(*) FROM packaging WHERE production_batch_id=? AND status<>'cancelled' AND deleted_at IS NULL",[$b['id']]))throw new RuntimeException('Annulation bloquée: la farine a été conditionnée.');$bulk=$this->row('SELECT * FROM bulk_flour_stocks WHERE production_batch_id=? FOR UPDATE',[$b['id']]);if($bulk&&(float)$bulk['quantity_kg']<(float)$b['output_quantity_kg'])throw new RuntimeException('Annulation bloquée: farine déjà consommée.');$wastes=$this->all('SELECT * FROM waste_stocks WHERE production_batch_id=? FOR UPDATE',[$b['id']]);$expected=(float)$this->scalar('SELECT COALESCE(SUM(quantity_kg),0) FROM production_waste_lines WHERE production_batch_id=? AND deleted_at IS NULL',[$b['id']]);$available=array_sum(array_map(function($x){return(float)$x['quantity_kg'];},$wastes));if($available+0.001<$expected)throw new RuntimeException('Annulation bloquée: déchets déjà consommés.');if($bulk){$this->query("UPDATE bulk_flour_stocks SET quantity_kg=0,status='cancelled' WHERE id=:id",['id'=>$bulk['id']]);$this->effect($rev,'bulk_flour_stocks',$bulk['id'],'quantity_kg',-$bulk['quantity_kg'],$bulk['quantity_kg'],0,null,null);}foreach($wastes as$w){$this->query("UPDATE waste_stocks SET quantity_kg=0,status='cancelled',storage_status='inactive' WHERE id=:id",['id'=>$w['id']]);$this->effect($rev,'waste_stocks',$w['id'],'quantity_kg',-$w['quantity_kg'],$w['quantity_kg'],0,null,null);}$this->query("UPDATE production_batches SET status='cancelled' WHERE id=:id",['id'=>$b['id']]);$feed=$this->row('SELECT * FROM machine_feeds WHERE id=? FOR UPDATE',[$b['machine_feed_id']]);if($feed)$this->reverseBss($feed,$rev,$u);}
