 private function reverseDistribution($d,$rev,$u){$s=$this->row('SELECT * FROM finished_stocks WHERE id=? FOR UPDATE',[$d['finished_stock_id']]);$afterKg=(float)$s['total_weight_kg']+(float)$d['total_weight_kg'];$afterBags=(int)$s['quantity_bags']+(int)$d['quantity_bags'];$this->query("UPDATE finished_stocks SET total_weight_kg=:kg,quantity_bags=:bags,status='active' WHERE id=:id",['kg'=>$afterKg,'bags'=>$afterBags,'id'=>$s['id']]);$this->effect($rev,'finished_stocks',$s['id'],'total_weight_kg',$d['total_weight_kg'],$s['total_weight_kg'],$afterKg,'stock_movements',$this->scalar('SELECT id FROM stock_movements WHERE distribution_id=? ORDER BY id DESC LIMIT 1',[$d['id']]));$this->query("INSERT INTO stock_movements(site_id,product_id,finished_stock_id,distribution_id,movement_type,quantity_bags,quantity_kg,stock_before_kg,stock_after_kg,movement_at,status,created_by) VALUES(:site,:product,:stock,:distribution,'adjustment',:bags,:kg,:before,:after,NOW(),'validated',:user)",['site'=>$d['site_id'],'product'=>$d['product_id'],'stock'=>$s['id'],'distribution'=>$d['id'],'bags'=>$d['quantity_bags'],'kg'=>$d['total_weight_kg'],'before'=>$s['total_weight_kg'],'after'=>$afterKg,'user'=>$u['id']]);$this->query("UPDATE distributions SET status='cancelled' WHERE id=:id",['id'=>$d['id']]);}
