 private function reverseEmptyPackagingReceipt($r,$rev,$u){$lines=$this->all('SELECT l.*,p.site_id FROM empty_packaging_receipt_lines l JOIN empty_packaging_purchase_lines pl ON pl.id=l.purchase_line_id JOIN empty_packaging_purchases p ON p.id=pl.purchase_id WHERE l.receipt_id=? FOR UPDATE',[$r['id']]);foreach($lines as$l){$s=$this->row('SELECT * FROM empty_packaging_stocks WHERE site_id=? AND packaging_item_id=(SELECT packaging_item_id FROM empty_packaging_purchase_lines WHERE id=?) FOR UPDATE',[$l['site_id'],$l['purchase_line_id']]);if($this->scalar("SELECT COUNT(*) FROM empty_packaging_movements WHERE stock_id=? AND movement_at>? AND movement_type IN('issue','consumption','transfer_out','defective')",[$s['id'],$r['received_at']]))throw new RuntimeException('Annulation bloquée: emballages reçus déjà consommés.');$after=(int)$s['physical_quantity']-(int)$l['quantity'];if($after<0)throw new RuntimeException('Stock emballages insuffisant.');$this->query('UPDATE empty_packaging_stocks SET physical_quantity=:q WHERE id=:id',['q'=>$after,'id'=>$s['id']]);$this->effect($rev,'empty_packaging_stocks',$s['id'],'physical_quantity',-$l['quantity'],$s['physical_quantity'],$after,null,null);$this->query('UPDATE empty_packaging_purchase_lines SET received_quantity=received_quantity-:q WHERE id=:id',['q'=>$l['quantity'],'id'=>$l['purchase_line_id']]);}$this->query("UPDATE empty_packaging_receipts SET status='cancelled' WHERE id=:id",['id'=>$r['id']]);$this->query("UPDATE empty_packaging_purchases SET status='approved' WHERE id=:id",['id'=>$r['purchase_id']]);}
