 private function policy($type){$p=$this->row("SELECT * FROM cancellation_policies WHERE entity_type=? AND status='active'",[$type]);if(!$p)throw new RuntimeException('Type d’annulation inconnu.');return$p;}
 private function record($type,$id,$lock){$map=['weighing'=>['weighings','id','site_id','reference'],'brs'=>['silo_movements','id','site_id','id'],'bss'=>['machine_feeds','id','site_id','id'],'transfer'=>['stock_transfers','id','source_site_id','transfer_number'],'production'=>['production_batches','id','site_id','batch_number'],'packaging'=>['packaging','id','site_id','id'],'distribution'=>['distributions','id','site_id','exit_voucher'],'waste_sale'=>['waste_sales','id','(SELECT site_id FROM waste_stocks WHERE id=waste_stock_id)','sale_number'],'waste_transfer'=>['waste_transfers','id','source_site_id','transfer_number'],'pelletization'=>['pellet_orders','id','site_id','order_number'],'empty_packaging_receipt'=>['empty_packaging_receipts','id','(SELECT site_id FROM empty_packaging_purchases WHERE id=purchase_id)','receipt_number'],'fuel_receipt'=>['fuel_receipts','id','(SELECT site_id FROM fuel_purchase_orders WHERE id=purchase_order_id)','receipt_number'],'butchery_receipt'=>['butchery_receipts','id','site_id','receipt_number']];if(!isset($map[$type]))throw new RuntimeException('Type non géré.');$m=$map[$type];$status=in_array($type,['brs','waste_sale','empty_packaging_receipt','fuel_receipt'],true)?"'validated'":'status';if($type==='empty_packaging_receipt'||$type==='fuel_receipt')$status="'received'";$sql="SELECT *,{$m[2]} site_id,{$status} status,{$m[3]} operation_reference FROM {$m[0]} WHERE {$m[1]}=?".($lock?' FOR UPDATE':'');$r=$this->row($sql,[$id]);if(!$r)throw new RuntimeException('Opération introuvable.');return$r;}
 private function needsApproval($status){return in_array($status,['validated','received','accepted','reserved','approved'],true);}
 private function cancelDocuments($type,$id,$reason,$u){$entities=['weighing'=>['weighings'],'brs'=>['silo_movements'],'bss'=>['silo_movements','machine_feeds'],'transfer'=>['stock_transfers'],'production'=>['production_batches'],'packaging'=>['packaging'],'distribution'=>['distributions'],'waste_transfer'=>['waste_transfers'],'pelletization'=>['pellet_orders'],'empty_packaging_receipt'=>['empty_packaging_receipts'],'fuel_receipt'=>['fuel_receipts'],'butchery_receipt'=>['butchery_receipts']];foreach($entities[$type]??[]as$e){foreach($this->all('SELECT * FROM documents WHERE entity_type=? AND entity_id=? AND status<>\'cancelled\' FOR UPDATE',[$e,$id])as$d){$this->query("UPDATE documents SET status='cancelled',cancelled_by=:user,cancelled_at=NOW() WHERE id=:id",['user'=>$u['id'],'id'=>$d['id']]);$this->query("INSERT INTO document_status_history(document_id,old_status,new_status,changed_by,reason) VALUES(:document,:old,'cancelled',:user,:reason)",['document'=>$d['id'],'old'=>$d['status'],'user'=>$u['id'],'reason'=>$reason]);}}}
 private function effect($rev,$table,$id,$field,$delta,$before,$after,$mt,$mid){$this->query('INSERT INTO cancellation_stock_effects(reversal_id,stock_table,stock_id,quantity_field,quantity_delta,quantity_before,quantity_after,original_movement_table,original_movement_id) VALUES(:rev,:table,:stock,:field,:delta,:before,:after,:mt,:mid)',['rev'=>$rev,'table'=>$table,'stock'=>$id,'field'=>$field,'delta'=>$delta,'before'=>$before,'after'=>$after,'mt'=>$mt,'mid'=>$mid]);}
 private function audit($req,$record,$rev,$u){$this->query("INSERT INTO activity_logs(user_id,site_id,action,module,entity_type,entity_id,description,new_values,ip_address,user_agent) VALUES(:user,:site,'cancel_execute','cancellations',:type,:entity,:description,:values,:ip,:agent)",['user'=>$u['id'],'site'=>$req['site_id'],'type'=>$req['entity_type'],'entity'=>$req['entity_id'],'description'=>'Contre-opération exécutée sans suppression du mouvement initial.','values'=>json_encode(['reversal_id'=>$rev,'reason'=>$req['reason'],'original_status'=>$record['status']],JSON_UNESCAPED_UNICODE),'ip'=>$_SERVER['REMOTE_ADDR']??null,'agent'=>substr($_SERVER['HTTP_USER_AGENT']??'CLI',0,255)]);}
 private function event($id,$type,$actor,$details){$this->query('INSERT INTO cancellation_events(request_id,event_type,actor_id,details) VALUES(:id,:type,:actor,:details)',['id'=>$id,'type'=>$type,'actor'=>$actor,'details'=>$details]);}private function row($s,$p=[]){$q=$this->db->prepare($s);$q->execute($p);return$q->fetch();}private function all($s,$p=[]){$q=$this->db->prepare($s);$q->execute($p);return$q->fetchAll();}private function scalar($s,$p=[]){$q=$this->db->prepare($s);$q->execute($p);return$q->fetchColumn();}private function query($s,$p=[]){$q=$this->db->prepare($s);$q->execute($p);return$q;}
}
